  assign io_forwardInfo_corrupt = corrupt;
  assign io_matched = req_valid & req_addr[47:6] == io_req_bits_addr[47:6];
  assign io_l1Miss = req_valid;
  assign io_wfi_wfiSafe = io_wfi_wfiSafe_last_REG;
endmodule

